SELECT DATE(generated_at) AS d, COUNT(*) AS n, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, candle_open_time + INTERVAL 1 MINUTE, generated_at))/1e6,3) AS avg_gen_s, ROUND(MAX(TIMESTAMPDIFF(MICROSECOND, candle_open_time + INTERVAL 1 MINUTE, generated_at))/1e6,3) AS max_gen_s, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, generated_at, created_at))/1e6,3) AS avg_persist_s, ROUND(MAX(TIMESTAMPDIFF(MICROSECOND, generated_at, created_at))/1e6,3) AS max_persist_s FROM crypto_ai.trade_signal WHERE interval_code='1m' AND generated_at BETWEEN '2026-10-11 00:00:00' AND '2026-10-13 00:00:00' GROUP BY DATE(generated_at) ORDER BY d;